"""Build a self-contained illustrative preview of the actual Telegram menus."""
from pathlib import Path
import base64,html
root=Path(__file__).resolve().parent.parent
avatar=base64.b64encode((root/'assets/roy-original.jpg').read_bytes()).decode()
style='''*{box-sizing:border-box}body{margin:0;background:#e9e5db;color:#25343d;font-family:Arial,sans-serif;padding:35px 20px}h1{font:700 29px Georgia,serif;margin:0 0 12px}.intro{max-width:920px;margin:0 auto 28px;line-height:1.55}.intro p{margin:7px 0}.phones{display:flex;gap:30px;justify-content:center;flex-wrap:wrap}.phone{width:390px;max-width:100%;border:7px solid #263942;border-radius:35px;background:#d6e4d5;overflow:hidden;box-shadow:0 15px 40px #22332c25}.bar{background:#fff;padding:15px;display:flex;align-items:center;gap:12px}.bar img{width:48px;height:48px;object-fit:cover;object-position:center 24%;border-radius:50%}.name{font-weight:bold;font-size:16px}.sub{font-size:12px;color:#74818a;margin-top:5px}.screen{padding:20px 13px 27px;background:radial-gradient(circle at 20% 20%,#ffffff2d 2px,transparent 3px);background-size:25px 25px;min-height:670px}.message{background:#fff;border-radius:14px 14px 14px 3px;padding:15px 15px 10px;line-height:1.45;font-size:15px;box-shadow:0 1px 3px #0001;white-space:pre-wrap}.time{text-align:right;color:#94a0a7;font-size:11px;margin-top:7px}.buttons{display:grid;grid-template-columns:1fr 1fr;gap:5px;margin-top:6px}.button{background:#486553b8;color:white;text-align:center;border-radius:6px;padding:13px 6px;font-size:13px;min-height:44px;display:flex;align-items:center;justify-content:center}.wide{grid-column:span 2}.tag{font-size:11px;text-transform:uppercase;letter-spacing:2px;color:#51665b;text-align:center;margin:0 0 12px;font-weight:bold}.note{font-size:13px;color:#56675d;max-width:850px;margin:25px auto 0;line-height:1.5}'''
menus=[('Главное меню', '🍯 МЕДОВЫЙ ПОТОК\nТаверна между мирами\n\nС возвращением, Элира.\nЧем займёмся?\n\n🪙 Золото: 1 250 зм\n✨ Вдохновение: есть', [('👤 Мой герой',False),('🪙 Кошелёк',False),('📜 Доска Роя',False),('🎲 Покер на костях',False),('🏆 Рейтинги',False),('🗝 Моё место',False),('🖐 Сделать ход',False),('📨 Мои заявки',False),('🤝 Сделка',False),('📖 Правила',False),('🎁 Лавка Роя',False),('🍯 Кошелёк Роя',False)]),('Карточка героя','🔒 КАРТОЧКА ПЕРСОНАЖА\n👤 Элира\nОтряд: Серебряный след\n\n🟢 Жива\nКласс брони: 16\nЗдоровье: 28/40\nСкорость: 30 футов · 6 клеток\nПассивное Восприятие: 12\n\n✨ Вдохновение Роя: есть — одно дополнительное действие\n🖐 Основное действие: доступно\n🎯 Дополнительное за визит: ещё не использовано\n\n🗝 Койка\n\n🎒 Предметы\n• Кольцо защиты · №12\n• Записка Роя · №18',[('🖐 Сделать ход',False),('🪙 Кошелёк',False),('🎲 Покер',False),('Обновить карточку',False),('🍯 К стойке Роя',True)])]
parts=['<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Медовый поток · оформление Роя</title><style>'+style+'</style><div class="intro"><h1>У стойки Роя</h1><p>Пример оформления меню бота «Медовый поток», версия 0.9.</p><p>Портрет — присланное изображение Роя. Герой и цифры ниже демонстрационные. Фон и цвета сообщений зависят от темы Telegram: бот управляет текстом и кнопками.</p></div><div class="phones">']
for title,text,buttons in menus:
    parts.append('<div class="phone"><div class="bar"><img alt="Рой" src="data:image/jpeg;base64,'+avatar+'"><div><div class="name">Рой | Медовый поток</div><div class="sub">бот · хозяин таверны</div></div></div><div class="screen"><div class="tag">'+html.escape(title)+'</div><div class="message">'+html.escape(text)+'<div class="time">18:35 ✓✓</div></div><div class="buttons">')
    for label,wide in buttons:parts.append('<div class="button'+(' wide' if wide else '')+'">'+html.escape(label)+'</div>')
    parts.append('</div></div></div>')
parts.append('</div><div class="note">Это макет меню, а не подключение к Telegram. Кнопки в этом файле показаны для просмотра; рабочие кнопки находятся в самом боте после обновления.</div></html>')
(root/'DESIGN_PREVIEW.html').write_text(''.join(parts),encoding='utf-8')
